Author:     John Bieling <john@thunderbird.net>
AuthorDate: Fri May 16 17:35:24 2025 +0100
Commit:     John Bieling <john@thunderbird.net>
CommitDate: Fri May 16 17:35:24 2025 +0100

    Bug 1966424 - Add support for the sessions permission and warn if the sessions API is used without requesting it. r=mkmelin


    This was a mishap while implementing the API, we should have requested
    the `sessions` permission. This patch removes the warning reported in
    the Bug and adds a warning if the permission is *not* requested. We will
    also actively reach out to developers to notify them of the upcoming
    backward incompatible change to require the permission.

    Differential Revision: https://phabricator.services.mozilla.com/D249753

diff --git a/mail/components/extensions/parent/ext-sessions.js b/mail/components/extensions/parent/ext-sessions.js
index 2c70780e695..ce73584dc1c 100644
--- a/mail/components/extensions/parent/ext-sessions.js
+++ b/mail/components/extensions/parent/ext-sessions.js
@@ -24,14 +24,29 @@ this.sessions = class extends ExtensionAPI {
     return {
       sessions: {
         setTabValue(tabId, key, value) {
+          if (!context.extension.hasPermission("sessions")) {
+            console.warn(
+              "Following Firefox, Thunderbird will soon require the `sessions` permission in order to use sessions.setTabValue()."
+            );
+          }
           const sessionData = getSessionData(tabId, context.extension);
           sessionData[key] = value;
         },
         getTabValue(tabId, key) {
+          if (!context.extension.hasPermission("sessions")) {
+            console.warn(
+              "Following Firefox, Thunderbird will soon require the `sessions` permission in order to use sessions.getTabValue()."
+            );
+          }
           const sessionData = getSessionData(tabId, context.extension);
           return sessionData[key];
         },
         removeTabValue(tabId, key) {
+          if (!context.extension.hasPermission("sessions")) {
+            console.warn(
+              "Following Firefox, Thunderbird will soon require the `sessions` permission in order to use sessions.removeTabValue()."
+            );
+          }
           const sessionData = getSessionData(tabId, context.extension);
           delete sessionData[key];
         },
